static lean_object* _init_lp_LeanSearchClient_LeanSearchClient_loogleUsage___closed__0() {
_start:
{
lean_object* x_1; 
x_1 = lean_mk_string_unchecked("Loogle Usage\n\nLoogle finds definitions and lemmas in various ways:\n\nBy constant:\n🔍 Real.sin\nfinds all lemmas whose statement somehow mentions the sine function.\n\nBy lemma name substring:\n🔍 \"differ\"\nfinds all lemmas that have \"differ\" somewhere in their lemma name.\n\nBy subexpression:\n🔍 _ * (_ ^ _)\nfinds all lemmas whose statements somewhere include a product where the second argument is raised to some power.\n\nThe pattern can also be non-linear, as in\n🔍 Real.sqrt \?a * Real.sqrt \?a\n\nIf the pattern has parameters, they are matched in any order. Both of these will find List.map:\n🔍 (\?a -> \?b) -> List \?a -> List \?b\n🔍 List \?a -> (\?a -> \?b) -> List \?b\n\nBy main conclusion:\n🔍 |- tsum _ = _ * tsum _\nfinds all lemmas where the conclusion (the subexpression to the right of all → and ∀) has the given shape.\n\nAs before, if the pattern has parameters, they are matched against the hypotheses of the lemma in any order; for example,\n🔍 |- _ < _ → tsum _ < tsum _\nwill find tsum_lt_tsum even though the hypothesis f i < g i is not the last.\n\nIf you pass more than one such search filter, separated by commas Loogle will return lemmas which match all of them. The search\n🔍 Real.sin, \"two\", tsum, _ * _, _ ^ _, |- _ < _ → _\nwoould find all lemmas which mention the constants Real.sin and tsum, have \"two\" as a substring of the lemma name, include a product and a power somewhere in the type, and have a hypothesis of the form _ < _ (if there were any such lemmas). Metavariables (\?a) are assigned independently in each filter.", 1551, 1516);
return x_1;
}
}
